source='''from collections import Counter

def transform(grid):
    g=[list(row) for row in grid]
    h,w=len(g),len(g[0])
    bg=Counter(v for row in g for v in row).most_common(1)[0][0]
    active=[any(v!=bg for v in row) for row in g]
    rows=[r for r,on in enumerate(active) if on]
    if len(rows)<2:
        return g
    # The foreground is arranged in two vertically separated copies. Locate
    # their row bands, then transfer the lower copy's rightward extensions.
    groups=[]
    for r in rows:
        if groups and r==groups[-1][-1]+1:
            groups[-1].append(r)
        else:
            groups.append([r])
    if len(groups)<2:
        return g
    upper,lower=groups[0],groups[1]
    offset=lower[0]-upper[0]
    for r in upper:
        s=r+offset
        if s not in lower:
            continue
        a={c for c,v in enumerate(g[r]) if v!=bg}
        b={c for c,v in enumerate(g[s]) if v!=bg}
        if not a or not b:
            continue
        right=max(a)
        # The lower copy has a longer right edge. Mark its missing suffix
        # in the upper copy with the task's highlight color.
        for c in range(right+1,w):
            if c in b:
                if g[r][c]==bg:
                    g[r][c]=1
            else:
                break
    return g
'''
